"""SYNTHETIC TEST DATA — NOT OFFICIAL STATISTICS.

A small FOLK1A-shaped cube whose numbers are generated by a formula, used only to make tests
deterministic and network-independent. It mirrors the real table's structure (variable ids,
total codes, label conventions, area levels) and is internally consistent: sexes sum to the
total, single ages sum to the age total, municipalities + Christiansø and regions both sum to
All Denmark. Tests that need real figures use the bundled snapshot in ``data/snapshot``.
"""

from __future__ import annotations

import itertools
import json
from collections.abc import Callable
from typing import Any

import httpx

AREAS = [  # (code, label, region)
    ("000", "All Denmark", None),
    ("084", "Region Hovedstaden", None),
    ("101", "Copenhagen", "084"),
    ("147", "Frederiksberg", "084"),
    ("411", "Christiansø", "084"),
    ("082", "Region Midtjylland", None),
    ("751", "Aarhus", "082"),
    ("461", "Odense", "082"),
    ("851", "Aalborg", "082"),
    ("706", "Syddjurs", "082"),
]
SEXES = [("TOT", "Total"), ("1", "Men"), ("2", "Women")]
AGES = [
    ("IALT", "Age, total"),
    ("0", "0 years"),
    ("1", "1 year"),
    ("20", "20 years"),
    ("35", "35 years"),
    ("50", "50 years"),
    ("70", "70 years"),
]
MARITAL = [("TOT", "Total"), ("U", "Never married")]
PERIODS = [f"{y}K{q}" for y in (2022, 2023, 2024) for q in (1, 2, 3, 4)]

LEAF_AREAS = [code for code, label, region in AREAS if region is not None]
REGIONS = [code for code, label, _ in AREAS if label.startswith("Region ")]


def leaf_value(area: str, sex: str, age: str, period: str) -> int:
    """Deterministic synthetic count for a leaf cell (single area, sex 1/2, single age)."""
    a = LEAF_AREAS.index(area)
    p = PERIODS.index(period)
    return 50 + 37 * a + 3 * int(age) + 5 * p + (7 if sex == "2" else 0) + (a * p) % 4


def cube() -> dict[tuple[str, str, str, str, str], int]:
    """Every (area, sex, age, marital=TOT, period) cell of the synthetic table."""
    singles = [a for a, _ in AGES if a != "IALT"]
    leaf: dict[tuple[str, str, str, str], int] = {
        (area, sex, age, period): leaf_value(area, sex, age, period)
        for area, sex, age, period in itertools.product(LEAF_AREAS, ["1", "2"], singles, PERIODS)
    }

    def area_members(code: str) -> list[str]:
        if code == "000":
            return LEAF_AREAS
        if code in REGIONS:
            return [c for c, _, region in AREAS if region == code]
        return [code]

    out: dict[tuple[str, str, str, str, str], int] = {}
    for (area, _, _), (sex, _), (age, _), period in itertools.product(AREAS, SEXES, AGES, PERIODS):
        members = area_members(area)
        sexes = ["1", "2"] if sex == "TOT" else [sex]
        ages = singles if age == "IALT" else [age]
        out[(area, sex, age, "TOT", period)] = sum(
            leaf[(m, s, a, period)] for m in members for s in sexes for a in ages
        )
    return out


def tableinfo(periods: list[str] | None = None, **overrides: Any) -> dict[str, Any]:
    periods = periods or PERIODS

    def var(vid: str, text: str, values: list[tuple[str, str]], time: bool = False) -> dict:
        return {
            "id": vid,
            "text": text,
            "elimination": not time,
            "time": time,
            "values": [{"id": i, "text": t} for i, t in values],
        }

    payload = {
        "id": "FOLK1A",
        "text": "Population at the first day of the quarter",
        "description": "SYNTHETIC test metadata modelled on FOLK1A",
        "unit": "Number",
        "suppressedDataValue": "0",
        "updated": "2026-08-10T08:00:00",
        "active": True,
        "contacts": [{"name": "Test Person", "phone": "+4500000000", "mail": "x@example.invalid"}],
        "documentation": {"id": "test", "url": "https://example.invalid/doc"},
        "variables": [
            var("OMRÅDE", "region", [(c, t) for c, t, _ in AREAS]),
            var("KØN", "sex", SEXES),
            var("ALDER", "age", AGES),
            var("CIVILSTAND", "marital status", MARITAL),
            var("Tid", "time", [(p, p.replace("K", "Q")) for p in periods], time=True),
        ],
    }
    payload.update(overrides)
    return payload


def render_csv(
    body: dict[str, Any],
    values: dict[tuple[str, ...], int] | None = None,
    mutate: Callable[[list[list[str]]], None] | None = None,
) -> str:
    """Answer a /v1/data CSV request like StatBank: header, then every requested cell."""
    values = values or cube()
    selected = {v["code"]: v["values"] for v in body["variables"]}
    order = ["OMRÅDE", "KØN", "ALDER", "CIVILSTAND", "Tid"]
    rows = [
        [*combo, str(values[combo])] for combo in itertools.product(*(selected[k] for k in order))
    ]
    if mutate:
        mutate(rows)
    header = ";".join(k.upper() for k in order) + ";INDHOLD"
    return "﻿" + "\n".join([header, *(";".join(r) for r in rows)]) + "\n"


def make_transport(
    *,
    info: dict[str, Any] | None = None,
    mutate: Callable[[list[list[str]]], None] | None = None,
    cell_limit: int | None = None,
    fail_with: int | None = None,
) -> httpx.MockTransport:
    """A mock StatBank API. ``cell_limit`` emulates the REQUEST-LIMIT error."""
    payload = info or tableinfo()
    values = cube()

    def handler(request: httpx.Request) -> httpx.Response:
        if fail_with is not None:
            return httpx.Response(fail_with, json={"errorTypeCode": "UNAVAILABLE", "message": "x"})
        body = json.loads(request.content)
        if request.url.path.endswith("/tableinfo"):
            return httpx.Response(200, json=payload)
        if request.url.path.endswith("/data"):
            cells = 1
            for v in body["variables"]:
                cells *= len(v["values"])
            if cell_limit is not None and cells > cell_limit:
                return httpx.Response(
                    400, json={"errorTypeCode": "REQUEST-LIMIT", "message": "over the limit"}
                )
            return httpx.Response(
                200,
                text=render_csv(body, values, mutate),
                headers={"content-type": "text/csv; charset=utf-8"},
            )
        return httpx.Response(404, json={"errorTypeCode": "NOT-FOUND", "message": "?"})

    return httpx.MockTransport(handler)
